import { Button } from "@/components/ui/button";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import type { DataTableFeatures } from "@/lib/table/features";
import type { ColumnDef, RowData } from "@tanstack/react-table";
import { MoreHorizontal } from "lucide-react";
import { useDataTableActions } from "./provider";
import { rowScopedActions } from "./utils";

/** The cell: a menu of the row-scoped actions this row is stamped with. */
export function DataTableActionsCell<TData>({
  row,
}: {
  row: { original: TData };
}) {
  const { actions, getRowId, getRowActions, getRowLabel, trigger } =
    useDataTableActions<TData>();
  const available = rowScopedActions(actions, getRowActions(row.original));
  if (available.length === 0) return null;
  const id = getRowId(row.original);
  // Never the row id: it is the internal key the wire uses, which for a
  // composite or opaque key reads as noise. Hosts name the row themselves.
  const label = getRowLabel?.(row.original);

  return (
    <div
      className="flex items-center justify-center"
      // The row itself opens the sheet on click and on Enter. Both bubble up
      // from the trigger — and, through React's tree, from the portalled menu
      // items — so both stop here. Only the keys that open the row are
      // stopped; everything else keeps bubbling to the row, the table, and
      // any app-level shortcut listening above them.
      onClick={(event) => event.stopPropagation()}
      onKeyDown={(event) => {
        if (event.key === "Enter" || event.key === " ") {
          event.stopPropagation();
        }
      }}
    >
      <DropdownMenu>
        <DropdownMenuTrigger asChild>
          <Button
            variant="ghost"
            size="icon-xs"
            className="size-5"
            aria-label={label ? `Actions for ${label}` : "Row actions"}
          >
            <MoreHorizontal />
          </Button>
        </DropdownMenuTrigger>
        <DropdownMenuContent align="end">
          {available.map((action) => (
            <DropdownMenuItem
              key={action.id}
              variant={
                action.variant === "destructive" ? "destructive" : "default"
              }
              onSelect={() =>
                trigger(action, { scope: "ids", ids: [id] }, { count: 1 })
              }
            >
              {action.label}
            </DropdownMenuItem>
          ))}
        </DropdownMenuContent>
      </DropdownMenu>
    </div>
  );
}

/**
 * A column that renders `DataTableActionsCell`. Append it to the generated
 * columns; it needs a `DataTableActionsProvider` above the table. The column
 * is hideable — pair it with a `columnVisibility` default of `{ [id]: false }`
 * to keep it hidden until enabled from the view options.
 */
export function createActionsColumn<TData extends RowData>(
  options: { id?: string; size?: number } = {},
): ColumnDef<DataTableFeatures, TData> {
  const { id = "actions", size = 40 } = options;
  return {
    id,
    header: () => <span className="sr-only">Actions</span>,
    cell: ({ row }) => <DataTableActionsCell row={row} />,
    enableSorting: false,
    enableHiding: true,
    enableResizing: false,
    size,
    minSize: size,
    maxSize: size,
    meta: { label: "Actions", kind: "actions" },
  };
}

"use client";

import { useDataTable } from "@/components/data-table/data-table-provider";
import { Button } from "@/components/ui/button";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuLabel,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import { useFilterState } from "@/lib/store/hooks/useFilterState";
import { ChevronDown } from "lucide-react";
import { useDataTableActions } from "./provider";
import { actionsForScope } from "./utils";

/**
 * Keep only the store keys that are filters. `sort`, `cursor`, `uuid` and
 * friends are table state, not a predicate, and the server would drop them
 * anyway — but sending them hides what the request is actually about.
 */
export function pickFilterValues(
  state: Record<string, unknown>,
  filterKeys: readonly string[],
): Record<string, unknown> {
  const filter: Record<string, unknown> = {};
  for (const key of filterKeys) {
    const value = state[key];
    if (value === null || value === undefined) continue;
    if (Array.isArray(value) && value.length === 0) continue;
    filter[key] = value;
  }
  return filter;
}

/**
 * "Apply to every row matching the current filters" — the filter scope.
 * Sits in the toolbar's `toolbarActions` slot. Sends `expected_count` from
 * the server's own `filterRowCount`, so a drifted set is caught server-side.
 *
 * That count is the table's `filterRows` prop, verbatim: without it there is
 * no number to promise and the menu stays disabled. It also stays disabled
 * while the table is fetching — `filterRows` still describes the previous
 * query then, and sending it with the new filters would only earn a
 * `count_mismatch`.
 */
export function DataTableActionsFilterMenu() {
  const { actions, trigger, isPending } = useDataTableActions();
  const { filterRows, filterFields, isLoading } = useDataTable();
  const state = useFilterState<Record<string, unknown>>();

  const filterActions = actionsForScope(actions, "filter");
  if (filterActions.length === 0) return null;

  const count = filterRows ?? 0;
  const filterKeys = filterFields.map((field) => String(field.value));

  return (
    <DropdownMenu>
      <DropdownMenuTrigger asChild>
        <Button
          variant="outline"
          size="sm"
          disabled={isPending || isLoading || count === 0}
          data-matching={count}
        >
          Actions
          <ChevronDown />
        </Button>
      </DropdownMenuTrigger>
      <DropdownMenuContent align="end">
        <DropdownMenuLabel className="text-muted-foreground font-normal">
          All {count.toLocaleString()} matching rows
        </DropdownMenuLabel>
        <DropdownMenuSeparator />
        {filterActions.map((action) => (
          <DropdownMenuItem
            key={action.id}
            variant={
              action.variant === "destructive" ? "destructive" : "default"
            }
            onSelect={() =>
              trigger(
                action,
                {
                  scope: "filter",
                  filter: pickFilterValues(state, filterKeys),
                  expected_count: count,
                },
                { count },
              )
            }
          >
            {action.label}
          </DropdownMenuItem>
        ))}
      </DropdownMenuContent>
    </DropdownMenu>
  );
}

import {
  ROW_ACTIONS_KEY,
  type ActionDescriptor,
  type ActionErrorCode,
  type ActionRequest,
  type ActionResponse,
  type ActionScope,
} from "@/lib/actions/types";

/**
 * Replace `{name}` placeholders. Unknown names are left as-is.
 *
 * `{one|other}` picks a form by `vars.count` — `"Delete {count} {log|logs}?"`
 * reads "Delete 1 log?" and "Delete 3 logs?". Descriptors travel as JSON, so
 * this is the only way copy can pluralise without a function.
 */
export function interpolate(
  template: string,
  vars: Record<string, string | number>,
): string {
  return template.replace(
    /\{(\w+)\}|\{([^{}|]*)\|([^{}|]*)\}/g,
    (match, name: string | undefined, one: string, other: string) => {
      if (name !== undefined) {
        return Object.hasOwn(vars, name) ? String(vars[name]) : match;
      }
      return Number(vars.count) === 1 ? one : other;
    },
  );
}

/** Read the server's `_actions` stamp off a row. Missing means "none". */
export function rowActionsOf(row: unknown): string[] {
  if (typeof row !== "object" || row === null) return [];
  const value = (row as Record<string, unknown>)[ROW_ACTIONS_KEY];
  return Array.isArray(value) ? value.filter((v) => typeof v === "string") : [];
}

export function actionsForScope(
  actions: readonly ActionDescriptor[],
  scope: ActionScope,
): ActionDescriptor[] {
  return actions.filter((action) => action.scope.includes(scope));
}

/** Row-scoped actions the row is stamped with, in descriptor order. */
export function rowScopedActions(
  actions: readonly ActionDescriptor[],
  rowActionIds: readonly string[],
): ActionDescriptor[] {
  return actionsForScope(actions, "row").filter((action) =>
    rowActionIds.includes(action.id),
  );
}

/**
 * Split a selection into the rows an action applies to and the rest.
 *
 * A bulk button stays enabled while *any* selected row qualifies — an
 * intersection would make bulk useless on a mixed list — and the request
 * carries only the eligible ids, with the skipped count surfaced in the
 * confirmation.
 */
export function partitionRows<TRow extends { original: unknown }>(
  rows: readonly TRow[],
  actionId: string,
  getRowActions: (row: TRow["original"]) => string[],
): { eligible: TRow[]; skipped: number } {
  const eligible = rows.filter((row) =>
    getRowActions(row.original).includes(actionId),
  );
  return { eligible, skipped: rows.length - eligible.length };
}

export function newCommandId(): string {
  const c = globalThis.crypto;
  if (c && typeof c.randomUUID === "function") return `cmd_${c.randomUUID()}`;
  return `cmd_${Date.now().toString(36)}_${Math.random().toString(36).slice(2, 10)}`;
}

/** The server said no. `code` mirrors `ActionError.error`. */
export class ActionRequestError extends Error {
  readonly code: ActionErrorCode;
  readonly status: number;
  /** Present on `count_mismatch`. */
  readonly actual?: number;

  constructor(code: ActionErrorCode, status: number, actual?: number) {
    super(code.replace(/_/g, " "));
    this.name = "ActionRequestError";
    this.code = code;
    this.status = status;
    if (actual !== undefined) this.actual = actual;
  }
}

const KNOWN_CODES: ReadonlySet<string> = new Set<ActionErrorCode>([
  "unknown_action",
  "scope_not_allowed",
  "invalid_request",
  "count_mismatch",
  "forbidden",
  "failed",
]);

/** One POST. Throws `ActionRequestError` for any non-2xx. */
export async function postAction(
  href: string,
  request: ActionRequest,
  fetcher: typeof fetch = fetch,
): Promise<ActionResponse> {
  const response = await fetcher(href, {
    method: "POST",
    headers: { "content-type": "application/json" },
    body: JSON.stringify(request),
  });

  let json: unknown = null;
  try {
    json = await response.json();
  } catch {
    // A non-JSON body is handled by the status check below.
  }

  if (!response.ok) {
    const body = (json ?? {}) as { error?: unknown; actual?: unknown };
    const code =
      typeof body.error === "string" && KNOWN_CODES.has(body.error)
        ? (body.error as ActionErrorCode)
        : "failed";
    const actual = typeof body.actual === "number" ? body.actual : undefined;
    throw new ActionRequestError(code, response.status, actual);
  }

  // A 2xx without a numeric `applied` is not "applied to 0" — it is a route
  // that does not speak the contract (204, an HTML page from a proxy, …).
  const body = (json ?? {}) as { applied?: unknown };
  if (typeof body.applied !== "number") {
    throw new ActionRequestError("failed", response.status);
  }
  return { applied: body.applied };
}
